import{_ as t,o as a,c as r,a4 as o}from"./chunks/framework.CzJ_HCFe.js";const p=JSON.parse('{"title":"Guest calculation production activation","description":"","frontmatter":{},"headers":[],"relativePath":"operations/guest-calculation-production-activation.md","filePath":"operations/guest-calculation-production-activation.md","lastUpdated":1788517140000}'),i={name:"operations/guest-calculation-production-activation.md"};function d(n,e,s,c,l,u){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="guest-calculation-production-activation" tabindex="-1">Guest calculation production activation <a class="header-anchor" href="#guest-calculation-production-activation" aria-label="Permalink to &quot;Guest calculation production activation&quot;">​</a></h1><p>Status: <strong>AGPL path approved; activation readiness incomplete</strong> Assessment timestamp: <code>2026-09-02T23:54:32+05:30</code> (<code>Asia/Kolkata</code>) Release refresh: <code>2026-09-04</code> (<code>Asia/Kolkata</code>) Panchangam production baseline: <code>571b805</code> Epic: <a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/234" target="_blank" rel="noreferrer">#234</a></p><p>This is the operator runbook for activating guest birth-profile calculation and Muhurtam election-chart screening. The owner approved the AGPL-compatible public-source path and today-launch sequence on 2026-09-04. The evidence and rollback checks below still apply to every executed release step.</p><p>Refresh this record immediately before any Preview, merge, deployment, or activation approval. Reconfirm branch heads, CI/security check URLs, exact Vercel deployment IDs, environment-name inventories, public probes, and restore refs; the values below are a dated assessment, not perpetual release evidence.</p><h2 id="current-state" tabindex="-1">Current state <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current state&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Component</th><th>State</th></tr></thead><tbody><tr><td>Panchangam profile/Muhurtam UI</td><td>Live with both remote client flags off</td></tr><tr><td>Astro guest routes</td><td>The gateway code is on Production <code>bc15eb6</code> with public flags off. <a href="https://github.com/socraticsurge/astro-unified-core/pull/168" target="_blank" rel="noreferrer">PR #168</a> supplies the AGPL source-release posture; stacked <a href="https://github.com/socraticsurge/astro-unified-core/pull/169" target="_blank" rel="noreferrer">PR #169</a> supplies governed Production-only public Nominatim. Both remain unmerged review candidates.</td></tr><tr><td>DashaFlow authenticated contracts</td><td><a href="https://github.com/socraticsurge/dashaflow-sidecar/pull/3" target="_blank" rel="noreferrer">PR #3</a> is green at <code>00f8fe2</code>; it adds AGPL/source disclosure and remains unmerged</td></tr><tr><td>Panchangam activation-readiness work</td><td><a href="https://github.com/socraticsurge/telugu-calendar-utilities/pull/451" target="_blank" rel="noreferrer">PR #451</a> is merged at <code>571b805</code>; both public client flags remain off</td></tr><tr><td>Licensing</td><td>Owner selected the AGPL-compatible public-source path on 2026-09-04. TCU <code>1.14.0</code>, DashaFlow PR #3, and the Astro AGPL release candidate must all merge and expose public exact-revision source before activation</td></tr><tr><td>Production geocoder/shared controls</td><td>PR #169 reuses fixed public Nominatim with the existing Turso database, no LocationIQ/Geoapify account, no API key, and no Upstash/Redis dependency. It is Production-only, submit-only, process-cached, attributed, guest/auth shared, code-capped at 1,000 attempts/day, and protected by an exclusive fenced send lease. After the five-per-minute guard, validation, cache lookup, and coalescing, guest clients are limited to 50 valid managed-provider misses per anchored 24 hours. That is nominally 5% of the configured pool and prevents one client identity from exhausting it, though a boundary overlap can reach 100 upstream attempts in one UTC day. An upstream <code>Retry-After</code> is persisted fleet-wide through exact-fence completion. Production configuration and owner approval remain pending.</td></tr><tr><td>Authenticated backend Preview</td><td>Astro <code>dpl_DJ9hcs2aPk5vHsjuZfVEzaVEJuoE</code> and DashaFlow <code>dpl_8jXdq9TWJXRsz41zgyfZUJ9gbVyy</code> passed exact-token birth/election contracts against an isolated staging database. Public Nominatim is deliberately fixture-only outside Production; the Panchangam owner review remains local.</td></tr></tbody></table><h2 id="hard-gates" tabindex="-1">Hard gates <a class="header-anchor" href="#hard-gates" aria-label="Permalink to &quot;Hard gates&quot;">​</a></h2><p>All boxes must be supported by links to evidence.</p><ul><li>[ ] #231 is updated to record the owner-selected AGPL-compatible Swiss Ephemeris and PySwissEph posture plus the final release evidence.</li><li>[x] #444 audits existing PyPI and live-service exposure.</li><li>[ ] #445 implements and verifies the selected licensing posture.</li><li>[ ] #449 is updated to record that the AGPL PySwissEph binding is retained under the selected AGPL-compatible posture; no proprietary wrapper grant or replacement is required for this path.</li><li>[ ] #443&#39;s DashaFlow producer invariants pass against the TCU consumers.</li><li>[ ] #233 records the provider, retention, cache, attribution, and abuse posture.</li><li>[ ] #446 implements and verifies the owner-approved geocoder and shared, fail-closed guest abuse controls. Candidate code is not certification.</li><li>[ ] #447 migrates and regression-tests the authenticated profile geocoder so guest activation does not leave a second ungoverned provider path.</li><li>[x] The exact Astro/DashaFlow backend pair is certified in protected Preview with an isolated staging database and paired token. Public-Nominatim behavior is fixture-tested there and rejected before network dispatch.</li><li>[ ] Logs, analytics, and application-controlled server/shared cache contain no profile name, birth payload, natal chart, raw place-search text, raw IP, provider key, or bearer token. Provider transit of the submitted city/town query is separately disclosed and governed by approved terms.</li><li>[ ] Browser requests contain no profile name or cookies. Calculation responses may contain the documented narrow natal- or election-chart results, but must not echo birth inputs, raw IPs, provider credentials, bearer credentials, or raw upstream diagnostics.</li><li>[ ] Place-search responses carry only allowlisted structured provider/data attribution links, and the Panchangam UI visibly renders those links beside returned results at desktop and mobile widths.</li><li>[ ] #448 records exact deployment/check IDs, probes, privacy evidence, screenshots, and rollback rehearsal <strong>after</strong> #443, #445, #446, #447, and #449 are complete.</li><li>[ ] Owner approvals are recorded independently for Preview configuration, each merge, each Production deployment/configuration change, and each public client-flag activation.</li></ul><h2 id="version-record" tabindex="-1">Version record <a class="header-anchor" href="#version-record" aria-label="Permalink to &quot;Version record&quot;">​</a></h2><p>Fill this table without secret values.</p><p>Do not reuse one value for production, candidate, or rollback. Record immutable deployment IDs rather than mutable aliases.</p><table tabindex="0"><thead><tr><th>Layer</th><th>Current Production commit</th><th>Candidate runtime/code commit</th><th>Restore ref</th><th>Preview deployment ID</th><th>Production deployment ID</th><th>CI/security evidence</th></tr></thead><tbody><tr><td>Panchangam</td><td><code>571b805</code></td><td><code>ffcfca4</code> in PR #456, documentation baseline <code>728a79b</code>, plus this security-semantics follow-up</td><td><code>origin/master</code>; <code>archive/guest-activation-readiness-2026-09-03-8b0bf74</code>; pre-follow-up <code>archive/tcu-nominatim-fairness-docs-pre-2026-09-04-728a79b</code></td><td>Local owner-review build only; the deployed client intentionally accepts the canonical Production API</td><td>Re-query the immutable <code>gh-pages</code> tip/tree immediately before publication</td><td>PR #456 was green at <code>728a79b</code>: 1,466 Python tests passed and 1 skipped locally; documentation freshness/build/output passed; GitHub checks passed. Rerun after this follow-up.</td></tr><tr><td>Astro</td><td><code>bc15eb60e214b94a5668403b79dffbfcf5ae8e77</code></td><td><code>f8c810d</code> in PR #168, then <code>07f1e10adec161d54a4d3da5ba4e1d8e7786f8cc</code> in stacked PR #169</td><td><code>origin/archive/astro-main-pre-guest-release-2026-09-04-519d686</code>; pre-review Nominatim archive <code>a7e013c</code></td><td><code>dpl_DJ9hcs2aPk5vHsjuZfVEzaVEJuoE</code> (Ready, protected; provider fixture-only)</td><td>Re-query exact Ready deployment of <code>bc15eb6</code> before mutation</td><td>PR #168 checks passed; PR #169 local verification passed 883 tests across 73 files, including 233 focused provider/security tests across 7 files, plus TypeScript, palette, routes, and a 27-page Production build. Lint reported 0 errors and one unchanged unused-type warning; independent review findings were remediated.</td></tr><tr><td>DashaFlow</td><td><code>d01c8db</code></td><td><code>00f8fe26444cd8e63511af5d0d54ae41d15c419a</code> in PR #3</td><td><code>origin/archive/dashaflow-master-pre-guest-release-2026-09-04-d01c8db</code></td><td><code>dpl_8jXdq9TWJXRsz41zgyfZUJ9gbVyy</code> (Ready, protected)</td><td>Re-query exact Ready deployment of <code>d01c8db</code> before mutation</td><td>133 local tests and all PR checks passed; exact-token birth/election calls passed against the isolated Astro Preview</td></tr></tbody></table><h2 id="environment-names-and-implementation-state" tabindex="-1">Environment names and implementation state <a class="header-anchor" href="#environment-names-and-implementation-state" aria-label="Permalink to &quot;Environment names and implementation state&quot;">​</a></h2><p>These are names only. Never record values here, in issues, or in browser code.</p><table tabindex="0"><thead><tr><th>Owner</th><th>Current implemented name</th><th>Current boundary</th></tr></thead><tbody><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_ENABLED</code></td><td>exact <code>true</code>; exercise independently</td></tr><tr><td>Panchangam build</td><td><code>VITE_BIRTH_PROFILE_API_BASE</code></td><td>implemented, but a deployed build accepts only the canonical Production Astro base; it cannot target a hosted Preview today</td></tr><tr><td>Panchangam build</td><td><code>VITE_ELECTION_CHART_API_BASE</code></td><td>same deployed-host restriction; it cannot target a hosted Preview today</td></tr><tr><td>Astro</td><td><code>GUEST_BIRTH_PROFILE_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>GUEST_ELECTION_CHART_ENABLED</code></td><td>exact <code>true</code>; deployed/ambiguous runtimes otherwise fail closed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_URL</code></td><td>approved HTTPS service only when deployed</td></tr><tr><td>Astro</td><td><code>DASHAFLOW_SIDECAR_TOKEN</code></td><td>server-only credential sent by Astro</td></tr><tr><td>DashaFlow</td><td><code>DASHAFLOW_API_TOKEN</code></td><td>server-only verifier; its value must match Astro&#39;s differently named token</td></tr><tr><td>Astro</td><td><code>GEOCODER_PROVIDER</code></td><td>Set <code>nominatim-public</code> in Production only after owner approval. Preview and real local development reject it and use fixtures.</td></tr><tr><td>Astro</td><td><code>GEOCODER_API_KEY</code></td><td>Must be absent for <code>nominatim-public</code>; a key is needed only if a dormant commercial adapter is selected in a later reviewed release.</td></tr><tr><td>Astro</td><td><code>GEOCODER_DAILY_REQUEST_LIMIT</code></td><td>Set a canonical value no greater than <code>1000</code> for public Nominatim. Guest and managed signed-in cache misses share the same Production provider row.</td></tr><tr><td>Astro</td><td><code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED</code></td><td>Set exact <code>true</code> together with Production public-Nominatim guest activation so signed-in and guest calls share one governed path. Preview remains fixture-only.</td></tr><tr><td>Astro</td><td><code>TURSO_DATABASE_URL</code>, <code>TURSO_AUTH_TOKEN</code></td><td>Existing database used for pseudonymous client/user/fleet counters and one non-personal provider-budget/lease row. No place query or result is stored there.</td></tr><tr><td>Astro</td><td><code>RATE_LIMIT_HMAC_SECRET</code></td><td>Existing server-only HMAC secret for pseudonymous client/user/fleet counter keys.</td></tr><tr><td>Astro runtime</td><td><code>VERCEL_ENV</code>, <code>VERCEL</code>, <code>NODE_ENV</code></td><td>implementation classifies only consistent explicit local or deployed markers; missing, unknown, self-hosted-production, or contradictory markers fail closed</td></tr></tbody></table><p>The selected provider contract is implemented in Astro PR #169. Public Nominatim is fixed and keyless; no LocationIQ, Geoapify, Upstash, or Redis account is required. It is intentionally unavailable in Preview and real local development, where provider behavior is fixture-tested. Production guest place search remains fail-closed until the signed-in migration flag is also exact <code>true</code>, ensuring both audiences share one Turso-backed budget and send lease.</p><h3 id="place-search-retention-and-quota-contract" tabindex="-1">Place-search retention and quota contract <a class="header-anchor" href="#place-search-retention-and-quota-contract" aria-label="Permalink to &quot;Place-search retention and quota contract&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Boundary</th><th>Permitted data</th><th>Retention / verification gate</th></tr></thead><tbody><tr><td>Panchangam browser request</td><td>Trimmed city/town query only; no profile name, cookie, birth date/time, or chart</td><td>Transient request state; browser network evidence required</td></tr><tr><td>Astro process state</td><td>Ephemeral HMAC client pseudonym; SHA-256 request key; at most five normalized provider rows</td><td>Bounded 256-entry process cache with a 24-hour TTL; no shared result cache</td></tr><tr><td>Turso limiter tables</td><td>Environment-scoped HMAC client/user/fleet keys plus one provider-family hash and integer count/timing fields</td><td>Window/day rollover and bounded cleanup; no raw query, result, IP, user ID, birth detail, coordinate, or credential</td></tr><tr><td>Public Nominatim</td><td>Deliberately submitted city/town query and Astro&#39;s server egress metadata; no profile name, birth date/time, or provider credential</td><td>Provider-controlled under the linked Nominatim and OSMF policies; one bounded Production smoke query only after approval</td></tr><tr><td>Sentry / application analytics</td><td>No request bodies, raw place query, provider URL query/key, birth payload, or chart</td><td>Verify configuration and inspect Preview events before activation</td></tr></tbody></table><p>The geocoder fleet ceiling is 30 calls per minute, shared by guest place search and the activated signed-in migration. The managed signed-in path also applies a ten-call-per-user minute limit. Public Nominatim adds a code-capped 1,000-attempt UTC-day budget and one exclusive 12,500 ms crash-recovery lease; normal completion establishes a fenced 1,100 ms cooldown before the next distributed send. When public Nominatim returns <code>429</code>, a bounded numeric or HTTP-date <code>Retry-After</code> replaces that normal cooldown fleet-wide through the same exact-fence update, up to 24 hours. Missing, malformed, past, or zero-delay guidance becomes 60 seconds. Guest place search applies a durable 50-request allowance of valid managed-provider cache misses per client and anchored 24-hour window. It runs after the five-per-minute guard, validation, cache lookup, and duplicate coalescing and has its own bounded two-second storage deadline. Malformed requests and reusable results do not spend it, though malformed requests may already spend the earlier route capacity, fleet, and minute guards. Fifty is nominally 5% of the configured pool and prevents one client identity from exhausting the provider&#39;s UTC-day allowance. Because the client window is anchored rather than UTC-aligned, a boundary overlap can reach 100 upstream attempts in one UTC day. Warm-process cache hits and coalesced duplicate callers spend no provider slot. These controls implement the public service&#39;s absolute one-request/second application ceiling; they are not a purchased quota or availability guarantee.</p><p>For Turso capacity planning, a successful guest place cache miss uses five admission-path row mutations: the capacity, fleet, minute-client, anchored daily-client, and provider-reservation rows. The conditional exact-fence completion update is accounted separately. Any four-write guest-place estimate predates the anchored daily-client guard and is no longer valid.</p><h2 id="isolated-preview-and-production-only-provider-sequence" tabindex="-1">Isolated Preview and Production-only provider sequence <a class="header-anchor" href="#isolated-preview-and-production-only-provider-sequence" aria-label="Permalink to &quot;Isolated Preview and Production-only provider sequence&quot;">​</a></h2><p>The protected Astro/DashaFlow backend pair has been certified with an exact shared bearer credential and an isolated staging Turso database. Birth-profile and election-chart contracts passed, including missing/wrong-token failures and shared limiter behavior. The public Nominatim endpoint is intentionally not a Preview dependency: code rejects it outside Production, while unit, route, and browser fixtures verify request shape, attribution, failures, and result handling. Do not weaken CORS, expose a protection credential to browser JavaScript, or point a hosted Preview browser at Production.</p><p>Before Production activation:</p><ol><li>Record the final TCU, Astro, and DashaFlow candidate commits, successful checks, immutable deployments, and named restore refs.</li><li>Complete the AGPL/public-source and PySwissEph rights gates; verify exact source links from the deployed revisions.</li><li>Merge and deploy the credentialed Astro callers with guest flags off, then deploy DashaFlow authentication and repeat all signed-in chart fixtures.</li><li>Provision and verify the limiter schema against the exact Production Turso database. Confirm quota headroom, budget five admission-path mutations for a successful guest place miss, account separately for exact-fence completion, and verify that request paths perform no DDL.</li><li>Configure <code>GEOCODER_PROVIDER=nominatim-public</code>, no geocoder API key, a daily limit no greater than <code>1000</code>, and keep <code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED=true</code>. With guest flags still off, verify signed-in profile create/edit and the shared provider row.</li><li>Publish and observe the reviewed WAF rule according to its separate approval gate. Verify an edge rejection does not invoke a function or Turso.</li><li>Complete the local Panchangam browser journey with fixtures: place search, linked attribution, calculation, save/reload, profile detail, Daily Horoscope reuse, Muhurtam reuse, and mobile/desktop screenshots.</li><li>After owner sign-off, enable only the birth guest route/client and perform one bounded Production place query plus one birth calculation. Inspect headers, logs, limiter row, privacy fields, and public source links.</li><li>Observe the birth-only release for the recorded window. Activate election charts separately only after its own owner review and smoke test.</li><li>Attach evidence and rollback results to #448 and the parent epic.</li></ol><h2 id="failure-matrix" tabindex="-1">Failure matrix <a class="header-anchor" href="#failure-matrix" aria-label="Permalink to &quot;Failure matrix&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Failure</th><th>Expected behavior</th></tr></thead><tbody><tr><td>Client flag absent/malformed</td><td>No remote call; manual profile entry or conservative unscreened Muhurtam result</td></tr><tr><td>Astro route flag off</td><td>Fixed 503; no geocoder/sidecar call</td></tr><tr><td>Shared Turso limiter missing/unavailable in Preview/Production</td><td>Fixed 503; no expensive calculation/provider call</td></tr><tr><td>Production geocoder configuration missing/unavailable</td><td>Place search 503; no arbitrary or commercial fallback</td></tr><tr><td>Guest client exceeds 50 valid managed-provider place-search misses in its anchored 24-hour window</td><td>Sanitized 429 with durable client-window retry guidance; no provider call</td></tr><tr><td>Public Nominatim returns 429</td><td>Sanitized 429; bounded upstream retry guidance is persisted fleet-wide through exact-fence completion. Missing, malformed, past, or zero-delay guidance becomes 60 seconds; the maximum is 24 hours</td></tr><tr><td>Authenticated migration flag absent/false</td><td>Production preserves its old unbudgeted signed-in Nominatim path; Preview fails closed. Never use this as a Nominatim incident rollback.</td></tr><tr><td>Authenticated migration exact <code>true</code>, provider/limit unavailable</td><td>Signed-in place-changing operation fails closed; no legacy or commercial fallback and no profile mutation</td></tr><tr><td>Sidecar token missing/bad</td><td>Fixed gateway error; no upstream diagnostic or token in response</td></tr><tr><td>Sidecar timeout/transient error</td><td>Up to two bounded attempts within the browser deadline, with one retry only for 502/503/504, then a fixed unavailable result</td></tr><tr><td>Malformed/inconsistent chart</td><td>502/invalid response; never save or score as verified</td></tr><tr><td>Unsupported or ambiguous civil time</td><td>422; offer manual entry</td></tr></tbody></table><h2 id="merge-and-production-sequence" tabindex="-1">Merge and Production sequence <a class="header-anchor" href="#merge-and-production-sequence" aria-label="Permalink to &quot;Merge and Production sequence&quot;">​</a></h2><p>Production starts only after every hard gate above is complete: parent decisions #231 and #233, audit #444, implementation gates #443, #445, #446, #447, and #449, then exact-chain certification #448. The owner must still approve merges. Preview approval, merge approval, Production deployment/configuration approval, and feature activation approval are separate decisions.</p><ol><li>With explicit merge approval, merge the Astro caller/source/geocoder stack first with guest flags off, then DashaFlow. Do not deploy either merely because its PR merged.</li><li>With separate deployment approval, deploy the exact recorded Astro commit with both guest route flags off and verify all existing credentialed signed-in callers. Keep the authenticated geocoder migration off until the Production provider/Turso configuration is ready.</li><li>Deploy the exact recorded DashaFlow commit and smoke every authenticated calculation route before any guest activation.</li><li>With both guest routes still off, select <code>nominatim-public</code>, keep the API key absent, set the approved daily ceiling, enable the authenticated geocoder migration, and smoke signed-in profile create/edit. Confirm that the shared provider budget and lease are active before proceeding.</li><li>With a distinct activation approval, enable Astro birth only and publish the Panchangam build with only <code>VITE_BIRTH_PROFILE_API_ENABLED=true</code>.</li><li>Smoke and observe birth profiles for the recorded window. Keep both election flags off throughout that observation period.</li><li>After evidence review and a separate election activation approval, enable the Astro election route and publish the election-enabled client build.</li><li>Record immutable Production deployment IDs, timestamps, probes, privacy/log checks, feature-flag states, and restore refs after every step.</li></ol><p>Publishing the Panchangam build may require a workflow/configuration change. <code>.github/workflows/</code> is frozen in this repository and its current path filters do not make a docs-only commit a production activation mechanism. Any workflow change requires explicit owner approval and its own reviewed branch.</p><h2 id="rollback" tabindex="-1">Rollback <a class="header-anchor" href="#rollback" aria-label="Permalink to &quot;Rollback&quot;">​</a></h2><p>Record distinct current-Production, candidate, and restore identifiers before each mutation. A mutable branch name, alias, or “previous deployment” label is not sufficient.</p><ul><li><strong>Feature kill:</strong> first set the matching Astro server flag false and redeploy, then publish a Panchangam build with the corresponding <code>VITE_*</code> flag absent or false. During token rollback, keep both routes off until old/new credentials have completed an approved overlap or coordinated cutover.</li><li><strong>Panchangam code:</strong> restore the recorded Production commit. The known pre-activation restore branch is <code>archive/guest-activation-readiness-2026-09-03-8b0bf74</code>; <code>origin/master</code> is the current <code>571b805</code> Production baseline at this refresh. Resolve and record both full commit IDs again immediately before release.</li><li><strong>Astro/DashaFlow:</strong> restore the separately recorded immutable deployment IDs and commits. Do not assume a Vercel alias still points to the reviewed build.</li><li><strong>Provider/control failure:</strong> turn both guest server flags off first, but keep <code>AUTH_PROFILE_MANAGED_GEOCODER_ENABLED=true</code> while Production can reach public Nominatim. Turning it off restores the old unbudgeted signed-in path. To stop Nominatim completely, leave that migration flag true and remove the provider selection so signed-in and guest place lookups fail closed together.</li><li><strong>Browser data:</strong> preserve the profile schema and stored records; disabling remote calculation must not make existing profiles unreadable.</li><li><strong>GitHub Pages:</strong> preserve and compare the complete published <code>gh-pages</code> tip and tree, not only <code>index.html</code>. The rollback manifest must include <code>CNAME</code>, all current feeds and per-city Lagna JSON, the Gochara snapshot, the retained Rasi Phalalu tree, built assets, and the site shell. Follow <a href="./gh-pages-retention">GitHub Pages retention and rollback</a>; do not repeat a partial orphan deployment that drops layered artifacts.</li></ul><h2 id="decision-links" tabindex="-1">Decision links <a class="header-anchor" href="#decision-links" aria-label="Permalink to &quot;Decision links&quot;">​</a></h2><ul><li><a href="https://operations.osmfoundation.org/policies/nominatim/" target="_blank" rel="noreferrer">Public Nominatim usage policy</a></li><li><a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noreferrer">OpenStreetMap copyright and attribution</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/231" target="_blank" rel="noreferrer">Licensing gate #231</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/444" target="_blank" rel="noreferrer">Existing-distribution audit #444</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/445" target="_blank" rel="noreferrer">License-posture implementation #445</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/449" target="_blank" rel="noreferrer">PySwissEph rights or replacement #449</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/233" target="_blank" rel="noreferrer">Geocoder gate #233</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/443" target="_blank" rel="noreferrer">Producer invariants #443</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/446" target="_blank" rel="noreferrer">Managed geocoder/shared controls #446</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/447" target="_blank" rel="noreferrer">Authenticated geocoder migration #447</a></li><li><a href="https://github.com/socraticsurge/telugu-calendar-utilities/issues/448" target="_blank" rel="noreferrer">Preview certification #448</a></li></ul>',36)])])}const m=t(i,[["render",d]]);export{p as __pageData,m as default};
